WITH input_rows ( id, message_id, provider_attachment_id, filename, mime_type, size_bytes, content_id, reference_url ) AS ( SELECT * FROM unnest( $1::uuid[], $2::uuid[], $3::text[], $4::varchar[], $5::varchar[], $6::bigint[], $7::varchar[], $8::text[] ) ) INSERT INTO email_attachments ( id, message_id, provider_attachment_id, filename, mime_type, size_bytes, content_id, reference_url ) SELECT id, message_id, provider_attachment_id, filename, mime_type, size_bytes, content_id, reference_url FROM input_rows ON CONFLICT (message_id, provider_attachment_id) DO UPDATE SET filename=EXCLUDED.filename,mime_type=EXCLUDED.mime_type, size_bytes=EXCLUDED.size_bytes,content_id=EXCLUDED.content_id,reference_url=EXCLUDED.reference_url
